namespace sv_30a0662a5441483aad9bdb68131419ac.Services;

public class AppointmentService
{
    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>
        {
            "Dr. Smith",
            "Dr. Johnson",
            "Dr. Patel",
            "Dr. Williams"
        });
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        return Task.FromResult(new List<string>
        {
            "9:00 AM",
            "10:00 AM",
            "11:00 AM",
            "1:00 PM",
            "2:00 PM",
            "3:00 PM"
        });
    }

    /// <summary>
    /// Validates patient data against server-side business rules.
    /// Returns a dictionary of field name -> error messages.
    /// </summary>
    public Task<Dictionary<string, List<string>>> ValidatePatientAsync(
        string email, string insuranceProvider, string doctor, string timeSlot)
    {
        var errors = new Dictionary<string, List<string>>();

        // Reject patients with outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(BookAppointmentModel.Email)] = ["Account has outstanding balance"];
        }

        // Reject self-pay with doctors who don't accept it
        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors[nameof(BookAppointmentModel.Doctor)] = ["Selected doctor does not accept self-pay patients"];
        }

        // Simulate race condition on time slot
        if (timeSlot == "10:00 AM")
        {
            errors[nameof(BookAppointmentModel.TimeSlot)] = ["This slot is no longer available"];
        }

        return Task.FromResult(errors);
    }
}

public class BookAppointmentModel
{
    // Step 1
    public string? PatientName { get; set; }
    public string? Email { get; set; }
    public string? Phone { get; set; }
    public string InsuranceProvider { get; set; } = "";

    // Step 2
    public string Doctor { get; set; } = "";
    public DateOnly? AppointmentDate { get; set; }
    public string TimeSlot { get; set; } = "";
    public string? ReasonForVisit { get; set; }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_30a0662a5441483aad9bdb68131419ac.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

<EditForm EditContext="editContext" OnSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    <h4>Step 1: Patient Information</h4>

    <div class="mb-3">
        <label class="form-label">Patient Name</label>
        <InputText class="form-control" @bind-Value="Model.PatientName" />
        <ValidationMessage For="() => Model.PatientName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email</label>
        <InputText class="form-control" @bind-Value="Model.Email" />
        <ValidationMessage For="() => Model.Email" />
    </div>

    <div class="mb-3">
        <label class="form-label">Phone</label>
        <InputText class="form-control" @bind-Value="Model.Phone" />
        <ValidationMessage For="() => Model.Phone" />
    </div>

    <div class="mb-3">
        <label class="form-label">Insurance Provider</label>
        <InputSelect class="form-select" @bind-Value="Model.InsuranceProvider">
            <option value="">-- Select --</option>
            <option value="Aetna">Aetna</option>
            <option value="BlueCross">BlueCross</option>
            <option value="Cigna">Cigna</option>
            <option value="UnitedHealth">UnitedHealth</option>
            <option value="None">None</option>
        </InputSelect>
        <ValidationMessage For="() => Model.InsuranceProvider" />
    </div>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
            Next
        </button>
    }

    @if (showStep2)
    {
        <hr />
        <h4>Step 2: Appointment Details</h4>

        <div class="mb-3">
            <label class="form-label">Preferred Doctor</label>
            <InputSelect class="form-select" @bind-Value="Model.Doctor">
                <option value="">-- Select --</option>
                @foreach (var doc in doctors)
                {
                    <option value="@doc">@doc</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.Doctor" />
        </div>

        <div class="mb-3">
            <label class="form-label">Date</label>
            <InputDate class="form-control" @bind-Value="Model.AppointmentDate" @bind:after="OnDateChanged" />
            <ValidationMessage For="() => Model.AppointmentDate" />
        </div>

        <div class="mb-3">
            <label class="form-label">Time Slot</label>
            <InputSelect class="form-select" @bind-Value="Model.TimeSlot">
                <option value="">-- Select --</option>
                @foreach (var slot in availableSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.TimeSlot" />
        </div>

        <div class="mb-3">
            <label class="form-label">Reason for Visit</label>
            <InputTextArea class="form-control" @bind-Value="Model.ReasonForVisit" />
            <ValidationMessage For="() => Model.ReasonForVisit" />
        </div>

        <button type="button" class="btn btn-warning me-2" @onclick="CheckAvailability" disabled="@isSubmitting">
            @(isSubmitting ? "Checking..." : "Check Availability")
        </button>
        <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked || isSubmitting)">
            Book Appointment
        </button>
    }
</EditForm>

@if (bookingConfirmed)
{
    <div class="alert alert-success mt-3">
        Appointment booked successfully!
    </div>
}

@code {
    private EditContext editContext = default!;
    private CustomValidator? customValidator;
    private BookAppointmentModel Model = new();
    private bool showStep2;
    private bool isSubmitting;
    private bool availabilityChecked;
    private bool bookingConfirmed;
    private List<string> doctors = new();
    private List<string> availableSlots = new();

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate step 1 fields manually
        var isValid = true;
        customValidator?.ClearErrors();

        var step1Errors = new Dictionary<string, List<string>>();

        if (string.IsNullOrWhiteSpace(Model.PatientName))
            step1Errors[nameof(Model.PatientName)] = ["Patient Name is required."];

        if (string.IsNullOrWhiteSpace(Model.Email))
            step1Errors[nameof(Model.Email)] = ["Email is required."];
        else if (!IsValidEmail(Model.Email))
            step1Errors[nameof(Model.Email)] = ["Please enter a valid email address."];

        if (string.IsNullOrWhiteSpace(Model.Phone))
            step1Errors[nameof(Model.Phone)] = ["Phone is required."];

        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
            step1Errors[nameof(Model.InsuranceProvider)] = ["Insurance Provider is required."];

        if (step1Errors.Count > 0)
        {
            customValidator?.DisplayErrors(step1Errors);
            return;
        }

        showStep2 = true;
        availabilityChecked = false;
    }

    private async Task OnDateChanged()
    {
        availabilityChecked = false;
        if (Model.AppointmentDate.HasValue && !string.IsNullOrEmpty(Model.Doctor))
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
        else
        {
            availableSlots = new();
        }
        Model.TimeSlot = "";
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        isSubmitting = true;

        // Validate step 2 fields
        var step2Errors = new Dictionary<string, List<string>>();

        if (string.IsNullOrWhiteSpace(Model.Doctor))
            step2Errors[nameof(Model.Doctor)] = ["Please select a doctor."];

        if (!Model.AppointmentDate.HasValue)
            step2Errors[nameof(Model.AppointmentDate)] = ["Date is required."];
        else if (Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
            step2Errors[nameof(Model.AppointmentDate)] = ["Date must be in the future."];

        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
            step2Errors[nameof(Model.TimeSlot)] = ["Please select a time slot."];

        if (string.IsNullOrWhiteSpace(Model.ReasonForVisit))
            step2Errors[nameof(Model.ReasonForVisit)] = ["Reason for visit is required."];
        else if (Model.ReasonForVisit.Length > 500)
            step2Errors[nameof(Model.ReasonForVisit)] = ["Reason for visit must be 500 characters or less."];

        if (step2Errors.Count > 0)
        {
            customValidator?.DisplayErrors(step2Errors);
            isSubmitting = false;
            return;
        }

        // Server-side validation
        var serverErrors = await AppointmentService.ValidatePatientAsync(
            Model.Email!, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);

        if (serverErrors.Count > 0)
        {
            customValidator?.DisplayErrors(serverErrors);
            isSubmitting = false;
            return;
        }

        availabilityChecked = true;
        isSubmitting = false;
    }

    private async Task HandleSubmit()
    {
        if (availabilityChecked)
        {
            bookingConfirmed = true;
        }
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}

using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Forms;

namespace sv_30a0662a5441483aad9bdb68131419ac.Components.Pages;

public class CustomValidator : ComponentBase
{
    [CascadingParameter]
    private EditContext? EditContext { get; set; }

    private ValidationMessageStore? messageStore;

    protected override void OnInitialized()
    {
        messageStore = new ValidationMessageStore(EditContext!);
        EditContext!.OnValidationRequested += (s, e) => messageStore.Clear();
        EditContext!.OnFieldChanged += (s, e) => messageStore.Clear(e.FieldIdentifier);
    }

    public void DisplayErrors(Dictionary<string, List<string>> errors)
    {
        foreach (var (field, messages) in errors)
        {
            foreach (var message in messages)
            {
                messageStore!.Add(EditContext!.Field(field), message);
            }
        }
        EditContext!.NotifyValidationStateChanged();
    }

    public void ClearErrors()
    {
        messageStore?.Clear();
        EditContext?.NotifyValidationStateChanged();
    }
}

