    {
        // Validate step 1 fields manually
        var isValid = true;
        customValidator?.ClearErrors();

        var step1Errors = new Dictionary<string, List<string>>();

        if (string.IsNullOrWhiteSpace(Model.PatientName))
            step1Errors[nameof(Model.PatientName)] = ["Patient Name is required."];

        if (string.IsNullOrWhiteSpace(Model.Email))
            step1Errors[nameof(Model.Email)] = ["Email is required."];
        else if (!IsValidEmail(Model.Email))
            step1Errors[nameof(Model.Email)] = ["Please enter a valid email address."];

        if (string.IsNullOrWhiteSpace(Model.Phone))
            step1Errors[nameof(Model.Phone)] = ["Phone is required."];

        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
            step1Errors[nameof(Model.InsuranceProvider)] = ["Insurance Provider is required."];

        if (step1Errors.Count > 0)
        {
            customValidator?.DisplayErrors(step1Errors);
            return;
        }

        showStep2 = true;
        availabilityChecked = false;
    }

    private async Task OnDateChanged()
    {
